            explanation = "This is an autosome linked recessive trait that can be transmitted from parents to the         offspring when both the partners are carrier for the gene (or heterozygous). The disease is controlled by a single pair of allele, HbA and HbS.on chromosome -11, The defect is caused by the substitution of Glutamic acid (Glu) by Valine (Val) at the sixth position of the beta globin chain of the haemoglobin molecule. The substitution of amino acid in the globin protein results due to the single base substitution at the sixth codon of the beta globin gene from GAG to GUG. Thalassemia is caused by mutations in the DNA of cells that make hemoglobin — the substance in red blood cells that carries oxygen throughout your body. This is an autosomal inheritance. Hemophilia is caused by a mutation or change, in one of the genes, that provides instructions for making the clotting factor proteins needed to form a blood clot. This change or mutation can prevent the clotting protein from working properly or to be missing altogether. These genes are located on the X chromosome. Phenylketonuria or PKU is inherited in families in an autosomal recessive pattern. A birth defect that causes an amino acid called phenylalanine to build up in the body.",
