        Question(
            id = "pyq_2025_136_716",
            questionText = "Given below are two statements : Statement I : The DNA fragments extracted from gel electrophoresis can be used in construction of recombinant DNA. Statement II : Smaller size DNA fragments are observed near anode while larger fragments are found near the wells in an agarose gel. In the light of the above statements, choose the most appropriate answer from the options given below :",
            options = listOf(
                    QuestionOption("A", "{'label': '1', 'text': 'Both statement I and statement II are correct (2) Both statement I and statement II are incorrect'}"),
                    QuestionOption("B", "{'label': '3', 'text': 'Statement I is correct but statement II is incorrect (4) Statement I is incorrect but statement II is correct'}")
            ),
            correctAnswerIndex = 0,
            explanation = "The cutting of DNA by restriction endonucleases results in the fragments of DNA. These fragments can be separated by a technique known as gel electrophoresis. The separated bands of DNA are cut out from the agarose gel and extracted from the gel piece. This step is known as elution. The DNA fragments purified in this way are used in constructing rDNA by joining them with cloning vectors. • In gel electrophoresis, the DNA fragments separate (resolve) according to their size through sieving effect provided by the agarose gel. Hence, the smaller the fragment size, the farther it moves from cathode towards anode.",
